    public function run(): void
    {
        /*
         * Large JSON columns are written in separate compact updates.
         * This follows the reference V2/V3 format and lowers the risk of
         * "MySQL server has gone away" errors on local XAMPP installations.
         */
        $now = now();

        DB::table('module_library_items')->updateOrInsert(
            ['module_code' => 'DATA-SCIENCE-BASIC-V2'],
            [
                'module_no' => 3,
                'title' => 'Introduction to Data Science',
                'year_level' => 'Year 1',
                'version_no' => 2,
                'version_name' => 'Introduction to Data Science Practice and MCQ Review',
                'version_code' => 'V2',
                'description' => 'Overview of the data science lifecycle, tools, roles, and real-world applications across industries. This version emphasizes code tracing, worked practice, debugging, MCQ reasoning, comparison of methods, and mastery evidence.',
                'estimated_minutes' => 610,
                'sort_order' => 8,
                'is_active' => true,
                'created_at' => $now,
                'updated_at' => $now,
            ]
        );

        DB::table('module_library_items')
            ->where('module_code', 'DATA-SCIENCE-BASIC-V2')
            ->update([
                'content_sections' => json_encode($this->contentSections(), JSON_UNESCAPED_UNICODE),
                'updated_at' => now(),
            ]);

        DB::table('module_library_items')
            ->where('module_code', 'DATA-SCIENCE-BASIC-V2')
            ->update([
                'mcq_questions' => json_encode($this->mcqQuestions(), JSON_UNESCAPED_UNICODE),
                'updated_at' => now(),
            ]);
    }

